import { useCallback, useEffect, useState } from 'react';

import { getItem, removeItem, setItem } from '@proton/shared/lib/helpers/storage';

import { sendErrorReport } from '../../utils/errorHandling';
import type { DecryptedLink } from '../_links';
import { useLinksActions, useLinksListing } from '../_links';
import type { Share, ShareWithKey } from '../_shares';
import useSharesState from '../_shares/useSharesState';
import { waitFor } from '../_utils';
import { usePhotos } from './PhotosProvider';

export type RECOVERY_STATE =
    | 'READY'
    | 'STARTED'
    | 'DECRYPTING'
    | 'DECRYPTED'
    | 'PREPARING'
    | 'PREPARED'
    | 'MOVING'
    | 'MOVED'
    | 'CLEANING'
    | 'SUCCEED'
    | 'FAILED';

const RECOVERY_STATE_CACHE_KEY = 'photos-recovery-state';

export const usePhotosRecovery = () => {
    const { shareId, linkId, deletePhotosShare } = usePhotos();
    const { getRestoredPhotosShares } = useSharesState();
    const { getCachedChildren, loadChildren } = useLinksListing();
    const { moveLinks } = useLinksActions();
    const [countOfUnrecoveredLinksLeft, setCountOfUnrecoveredLinksLeft] = useState<number>(0);
    const [countOfFailedLinks, setCountOfFailedLinks] = useState<number>(0);
    const [state, setState] = useState<RECOVERY_STATE>('READY');
    const [restoredData, setRestoredData] = useState<{ links: DecryptedLink[]; shareId: string }[]>([]);
    const [needsRecovery, setNeedsRecovery] = useState<boolean>(false);

    const [restoredShares, setRestoredShares] = useState<Share[] | ShareWithKey[] | undefined>();

    useEffect(() => {
        const shares = getRestoredPhotosShares();
        setRestoredShares(shares);
        setNeedsRecovery(!!shares?.length);
    }, [getRestoredPhotosShares]);
    const handleFailed = (e: Error) => {
        setState('FAILED');
        setItem(RECOVERY_STATE_CACHE_KEY, 'failed');
        sendErrorReport(e);
    };

    const handleDecryptLinks = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[]) => {
            for (const share of shares) {
                await loadChildren(abortSignal, share.shareId, share.rootLinkId);
                await waitFor(
                    () => {
                        const { isDecrypting } = getCachedChildren(abortSignal, share.shareId, share.rootLinkId);
                        return !isDecrypting;
                    },
                    { abortSignal }
                );
            }
        },
        [getCachedChildren, loadChildren]
    );

    const handlePrepareLinks = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[]) => {
            let allRestoredData: { links: DecryptedLink[]; shareId: string }[] = [];
            let totalNbLinks: number = 0;

            for (const share of shares) {
                const { links } = getCachedChildren(abortSignal, share.shareId, share.rootLinkId);
                allRestoredData.push({
                    links,
                    shareId: share.shareId,
                });
                totalNbLinks += links.length;
            }
            return { allRestoredData, totalNbLinks };
        },
        [getCachedChildren]
    );

    const safelyDeleteShares = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[]) => {
            for (const share of shares) {
                const { links } = getCachedChildren(abortSignal, share.shareId, share.rootLinkId);
                if (!links.length) {
                    await deletePhotosShare(share.volumeId, share.shareId);
                }
            }
        },
        [deletePhotosShare, getCachedChildren]
    );

    const handleMoveLinks = useCallback(
        async (
            abortSignal: AbortSignal,
            {
                dataList,
                newLinkId,
            }: {
                dataList: { links: DecryptedLink[]; shareId: string }[];
                newLinkId: string;
            }
        ) => {
            for (const data of dataList) {
                await moveLinks(abortSignal, {
                    shareId: data.shareId,
                    linkIds: data.links.map((link) => link.linkId),
                    newParentLinkId: newLinkId,
                    newShareId: shareId,
                    onMoved: () => setCountOfUnrecoveredLinksLeft((prevState) => prevState - 1),
                    onError: () => {
                        setCountOfUnrecoveredLinksLeft((prevState) => prevState - 1);
                        setCountOfFailedLinks((prevState) => prevState + 1);
                    },
                });
            }
        },
        [moveLinks, shareId]
    );

    useEffect(() => {
        if (state !== 'STARTED' || !linkId || !restoredShares) {
            return;
        }
        const abortController = new AbortController();
        setState('DECRYPTING');
        void handleDecryptLinks(abortController.signal, restoredShares)
            .then(() => {
                setState('DECRYPTED');
            })
            .catch(handleFailed);
    }, [handleDecryptLinks, linkId, restoredShares, state]);

    useEffect(() => {
        const abortController = new AbortController();
        if (state !== 'DECRYPTED' || !restoredShares) {
            return;
        }
        setState('PREPARING');
        void handlePrepareLinks(abortController.signal, restoredShares)
            .then(({ allRestoredData, totalNbLinks }) => {
                setRestoredData(allRestoredData);
                if (!!totalNbLinks) {
                    setCountOfUnrecoveredLinksLeft(totalNbLinks);
                }
                setState('PREPARED');
            })
            .catch(handleFailed);
        return () => {
            abortController.abort();
        };
    }, [handlePrepareLinks, restoredShares, state]);

    useEffect(() => {
        if (state !== 'PREPARED' || !linkId) {
            return;
        }
        const abortController = new AbortController();
        setState('MOVING');
        void handleMoveLinks(abortController.signal, {
            newLinkId: linkId,
            dataList: restoredData,
        })
            .then(() => {
                setState('MOVED');
            })
            .catch(handleFailed);

        // Moved is done in the background, so we don't abort it on rerender
    }, [countOfUnrecoveredLinksLeft, handleMoveLinks, linkId, restoredData, state]);

    useEffect(() => {
        if (state !== 'MOVED' || !restoredShares || countOfUnrecoveredLinksLeft !== 0) {
            return;
        }
        const abortController = new AbortController();
        setState('CLEANING');
        void safelyDeleteShares(abortController.signal, restoredShares)
            .then(() => {
                // We still want to remove empty shares if possible,
                // but we should say to the user that it failed since not every file were recovered
                if (countOfFailedLinks) {
                    return Promise.reject(new Error('Failed to move recovered photos'));
                }
                removeItem(RECOVERY_STATE_CACHE_KEY);
                setState('SUCCEED');
            })
            .catch(handleFailed);

        return () => {
            abortController.abort();
        };
    }, [countOfFailedLinks, countOfUnrecoveredLinksLeft, restoredShares, safelyDeleteShares, state]);

    const start = useCallback(() => {
        setItem(RECOVERY_STATE_CACHE_KEY, 'progress');
        setState('STARTED');
    }, []);

    useEffect(() => {
        if (state !== 'READY') {
            return;
        }
        const cachedRecoveryState = getItem(RECOVERY_STATE_CACHE_KEY);
        if (cachedRecoveryState === 'progress') {
            setState('STARTED');
        } else if (cachedRecoveryState === 'failed') {
            setState('FAILED');
        }
    }, [state]);
    return {
        needsRecovery,
        countOfUnrecoveredLinksLeft,
        countOfFailedLinks,
        start,
        state,
    };
};
import { act, renderHook, waitFor } from '@testing-library/react';

import { SupportedMimeTypes } from '@proton/shared/lib/drive/constants';
import { getItem, removeItem, setItem } from '@proton/shared/lib/helpers/storage';

import type { DecryptedLink } from '../_links';
import { useLinksActions, useLinksListing } from '../_links';
import useSharesState from '../_shares/useSharesState';
import { usePhotos } from './PhotosProvider';
import { usePhotosRecovery } from './usePhotosRecovery';

function generateDecryptedLink(linkId = 'linkId'): DecryptedLink {
    return {
        encryptedName: 'name',
        name: 'name',
        linkId,
        createTime: 323212,
        digests: { sha1: '' },
        fileModifyTime: 323212,
        parentLinkId: 'parentLinkId',
        isFile: true,
        mimeType: SupportedMimeTypes.jpg,
        hash: 'hash',
        size: 233,
        metaDataModifyTime: 323212,
        trashed: 0,
        hasThumbnail: false,
        isShared: false,
        rootShareId: 'rootShareId',
        volumeId: 'volumeId',
    };
}

jest.mock('../_links', () => {
    const useLinksActions = jest.fn();
    const useLinksListing = jest.fn();
    return { useLinksActions, useLinksListing };
});

jest.mock('../_shares/useSharesState');

jest.mock('./PhotosProvider', () => {
    return {
        usePhotos: jest.fn(),
    };
});

jest.mock('../_utils', () => ({
    waitFor: jest.fn().mockImplementation(async (callback) => {
        callback();
    }),
}));

jest.mock('@proton/shared/lib/helpers/storage', () => ({
    getItem: jest.fn(),
    removeItem: jest.fn(),
    setItem: jest.fn(),
}));

jest.mock('../../utils/errorHandling');

const mockedRemoveItem = jest.mocked(removeItem);
const mockedGetItem = jest.mocked(getItem);
const mockedSetItem = jest.mocked(setItem);

describe('usePhotosRecovery', () => {
    const links = [generateDecryptedLink('linkId1'), generateDecryptedLink('linkId2')];
    const mockedUsePhotos = jest.mocked(usePhotos);
    const mockedUseLinksListing = jest.mocked(useLinksListing);
    const mockedUseLinksActions = jest.mocked(useLinksActions);
    const mockedUseShareState = jest.mocked(useSharesState);
    const mockedGetCachedChildren = jest.fn();
    const mockedLoadChildren = jest.fn();
    const mockedMoveLinks = jest.fn();
    const mockedDeletePhotosShare = jest.fn();

    beforeEach(() => {
        jest.clearAllMocks();
        mockedDeletePhotosShare.mockResolvedValue(undefined);
        mockedLoadChildren.mockResolvedValue(undefined);

        mockedMoveLinks.mockImplementation(
            async (abortSignal: AbortSignal, { linkIds, onMoved }: { linkIds: string[]; onMoved?: () => void }) => {
                // Reproduce the async behavior of moveLinks
                linkIds.forEach(() => setTimeout(() => onMoved?.(), 10));
            }
        );

        // @ts-ignore
        mockedUseLinksListing.mockReturnValue({
            loadChildren: mockedLoadChildren,
            getCachedChildren: mockedGetCachedChildren,
        });
        // @ts-ignore
        mockedUsePhotos.mockReturnValue({
            shareId: 'shareId',
            linkId: 'linkId',
            deletePhotosShare: mockedDeletePhotosShare,
        });
        // @ts-ignore
        mockedUseLinksActions.mockReturnValue({
            moveLinks: mockedMoveLinks,
        });
        // @ts-ignore
        mockedUseShareState.mockReturnValue({
            getRestoredPhotosShares: () => [
                {
                    addressId: 'addressId',
                    shareId: 'shareId',
                    rootLinkId: 'rootLinkId',
                    volumeId: 'volumeId',
                    creator: 'creator',
                    isLocked: false,
                    isDefault: false,
                    isVolumeSoftDeleted: false,
                    possibleKeyPackets: ['dsad'],
                    type: 4,
                    state: 1,
                    createTime: 1234,
                },
            ],
        });
    });

    it('should pass all state if files need to be recovered', async () => {
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Decrypting step
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Preparing step
        mockedGetCachedChildren.mockReturnValueOnce({ links: [], isDecrypting: false }); // Deleting step
        const { result } = renderHook(() => usePhotosRecovery());
        act(() => {
            result.current.start();
        });

        await waitFor(() => expect(result.current.state).toEqual('SUCCEED'));
        expect(result.current.countOfUnrecoveredLinksLeft).toEqual(0);
        expect(mockedGetCachedChildren).toHaveBeenCalledTimes(3);
        expect(mockedMoveLinks).toHaveBeenCalledTimes(1);
        expect(mockedLoadChildren).toHaveBeenCalledTimes(1);
        expect(mockedDeletePhotosShare).toHaveBeenCalledTimes(1);
        expect(result.current.countOfUnrecoveredLinksLeft).toEqual(0);
        expect(mockedRemoveItem).toHaveBeenCalledTimes(1);
        expect(mockedRemoveItem).toHaveBeenCalledWith('photos-recovery-state');
    });

    it('should pass and set errors count if some moves failed', async () => {
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Decrypting step
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Preparing step
        mockedGetCachedChildren.mockReturnValueOnce({ links: [links[0]], isDecrypting: false }); // Deleting step
        mockedMoveLinks.mockImplementation(
            async (
                abortSignal: AbortSignal,
                { linkIds, onMoved, onError }: { linkIds: string[]; onMoved?: () => void; onError?: () => void }
            ) => {
                linkIds.forEach((linkId) => {
                    if (linkId === 'linkId2') {
                        onError?.();
                    } else {
                        onMoved?.();
                    }
                });
            }
        );
        const { result } = renderHook(() => usePhotosRecovery());
        act(() => {
            result.current.start();
        });

        await waitFor(() => expect(result.current.state).toEqual('FAILED'));
        expect(result.current.countOfFailedLinks).toEqual(1);
        expect(result.current.countOfUnrecoveredLinksLeft).toEqual(0);
        expect(result.current.state).toEqual('FAILED');
        expect(mockedDeletePhotosShare).toHaveBeenCalledTimes(0);
        expect(mockedGetItem).toHaveBeenCalledTimes(1);
        expect(mockedSetItem).toHaveBeenCalledTimes(2);
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'progress');
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'failed');
    });

    it('should failed if deleteShare failed', async () => {
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Decrypting step
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Preparing step
        mockedGetCachedChildren.mockReturnValueOnce({ links: [], isDecrypting: false }); // Deleting step
        mockedDeletePhotosShare.mockRejectedValue(undefined);
        const { result } = renderHook(() => usePhotosRecovery());
        act(() => {
            result.current.start();
        });

        await waitFor(() => expect(result.current.state).toEqual('FAILED'));
        expect(mockedDeletePhotosShare).toHaveBeenCalledTimes(1);

        expect(mockedGetItem).toHaveBeenCalledTimes(1);
        expect(mockedSetItem).toHaveBeenCalledTimes(2);
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'progress');
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'failed');
    });

    it('should failed if loadChildren failed', async () => {
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Decrypting step
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Preparing step
        mockedGetCachedChildren.mockReturnValueOnce({ links: [], isDecrypting: false }); // Deleting step
        mockedLoadChildren.mockRejectedValue(undefined);
        const { result } = renderHook(() => usePhotosRecovery());
        act(() => {
            result.current.start();
        });

        await waitFor(() => expect(result.current.state).toEqual('FAILED'));
        expect(mockedDeletePhotosShare).toHaveBeenCalledTimes(0);
        expect(mockedGetCachedChildren).toHaveBeenCalledTimes(0);

        expect(mockedGetItem).toHaveBeenCalledTimes(1);
        expect(mockedSetItem).toHaveBeenCalledTimes(2);
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'progress');
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'failed');
    });

    it('should failed if moveLinks helper failed', async () => {
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Decrypting step
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Preparing step
        mockedGetCachedChildren.mockReturnValueOnce({ links: [], isDecrypting: false }); // Deleting step
        mockedMoveLinks.mockRejectedValue(undefined);
        const { result } = renderHook(() => usePhotosRecovery());
        act(() => {
            result.current.start();
        });

        await waitFor(() => expect(result.current.state).toEqual('FAILED'));
        expect(mockedDeletePhotosShare).toHaveBeenCalledTimes(0);
        expect(mockedMoveLinks).toHaveBeenCalledTimes(1);
        expect(mockedGetCachedChildren).toHaveBeenCalledTimes(2);
        expect(mockedGetItem).toHaveBeenCalledTimes(1);
        expect(mockedSetItem).toHaveBeenCalledTimes(2);
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'progress');
        expect(mockedSetItem).toHaveBeenCalledWith('photos-recovery-state', 'failed');
    });

    it('should start the process if localStorage value was set to progress', async () => {
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Decrypting step
        mockedGetCachedChildren.mockReturnValueOnce({ links, isDecrypting: false }); // Preparing step
        mockedGetCachedChildren.mockReturnValueOnce({ links: [], isDecrypting: false }); // Deleting step
        mockedGetItem.mockReturnValueOnce('progress');
        const { result } = renderHook(() => usePhotosRecovery());

        await waitFor(() => expect(result.current.state).toEqual('SUCCEED'));
        expect(mockedGetItem).toHaveBeenCalledTimes(1);
    });

    it('should set state to failed if localStorage value was set to failed', async () => {
        mockedGetItem.mockReturnValueOnce('failed');
        const { result } = renderHook(() => usePhotosRecovery());

        await waitFor(() => expect(result.current.state).toEqual('FAILED'));
    });
});

import { createContext, useCallback, useContext, useRef } from 'react';

import { queryFolderChildren } from '@proton/shared/lib/api/drive/folder';
import { queryLinkMetaBatch, queryVolumeLinkMetaBatch } from '@proton/shared/lib/api/drive/link';
import { BATCH_REQUEST_SIZE } from '@proton/shared/lib/drive/constants';
import type { LinkChildrenResult, LinkMetaBatchPayload } from '@proton/shared/lib/interfaces/drive/link';
import chunk from '@proton/utils/chunk';
import isTruthy from '@proton/utils/isTruthy';

import { linkMetaToEncryptedLink, useDebouncedRequest } from '../../_api';
import { waitFor } from '../../_utils';
import type { DecryptedLink, EncryptedLink } from './../interface';
import useLinksState, { isLinkDecrypted } from './../useLinksState';
import type { FetchLoadLinksMeta, FetchLoadLinksMetaByVolume } from './interface';
import { useBookmarksLinksListing } from './useBookmarksLinksListing';
import type { FetchMeta, FetchResponse, SortParams } from './useLinksListingHelpers';
import { PAGE_SIZE, sortParamsToServerSortArgs, useLinksListingHelpers } from './useLinksListingHelpers';
import { useSharedLinksListing } from './useSharedLinksListing';
import { useSharedWithMeLinksListingByVolume } from './useSharedWithMeLinksListingByVolume';
import { useTrashedLinksListing } from './useTrashedLinksListing';

type FetchState = {
    [shareId: string]: FetchShareState;
};

type FetchShareState = {
    folders: {
        [linkId: string]: {
            // all represents version for all files in the folder, whereas
            // foldersOnly is state of requesting only folders for the given
            // folder. In case `all` is ongoing, `foldersOnly` version waits
            // till that is done. See `fetchChildrenNextPage` for more info.
            all: FetchMeta;
            foldersOnly: FetchMeta;
        };
    };
    links: {
        [key: string]: FetchMeta;
    };
};

/**
 * Provides way to list links, such as folder links or
 * trashed links or shared links, and ensure the links are decrypted.
 * The typical usage should be as follow:
 *
 *      const listing = useLinksListingProvider();
 *
 *      // getCachedChildren returns links right away.
 *      // abortSignal is used for background decryption of stale links
 *      // (links not loaded by listing, but using events, for example).
 *      const children = listing.getCachedChildren(abortSignal, shareId, linkId);
 *
 *      useEffect(() => {
 *          const ac = new AbortController();
 *          // Load and decrypt all children for given folder.
 *          linksListing.loadChildren(ac.signal, shareId, linkId)
 *          return () => {
 *              // Stop the load operation when its not needed anymore.
 *              // E.g., different folder was requested.
 *              ac.abort();
 *          };
 *      }, [shareId, linkId]);
 */
export function useLinksListingProvider() {
    const debouncedRequest = useDebouncedRequest();
    const linksState = useLinksState();
    const trashedLinksListing = useTrashedLinksListing();
    const sharedLinksListing = useSharedLinksListing();
    const bookmarksLinksListing = useBookmarksLinksListing();
    const sharedWithMeLinksListingByVolume = useSharedWithMeLinksListingByVolume();

    const { cacheLoadedLinks, fetchNextPageWithSortingHelper, loadFullListing, getDecryptedLinksAndDecryptRest } =
        useLinksListingHelpers();
    const state = useRef<FetchState>({});

    /**
     * getShareFetchState returns state for given `shareId`.
     * It ensures that the share is present in the state.
     */
    const getShareFetchState = (shareId: string): FetchShareState => {
        if (state.current[shareId]) {
            return state.current[shareId];
        }
        state.current[shareId] = {
            folders: {},
            links: {},
        };

        return state.current[shareId];
    };

    const fetchChildrenPage = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentLinkId: string,
        sorting: SortParams,
        page: number,
        foldersOnly?: boolean,
        showNotification = true
    ): Promise<FetchResponse> => {
        const { Links } = await debouncedRequest<LinkChildrenResult>(
            {
                ...queryFolderChildren(shareId, parentLinkId, {
                    ...sortParamsToServerSortArgs(sorting),
                    PageSize: PAGE_SIZE,
                    Page: page,
                    FoldersOnly: foldersOnly ? 1 : 0,
                }),
                silence: !showNotification,
            },
            abortSignal
        );
        return { links: Links.map((link) => linkMetaToEncryptedLink(link, shareId)), parents: [] };
    };

    /**
     * Fetches next page for the given folder. If request for `foldersOnly`
     * is made and there is already ongoing request for all files for the same folder,
     * it waits till its finished to not ask for the same links twice.
     */
    const fetchChildrenNextPage = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentLinkId: string,
        sorting?: SortParams,
        foldersOnly?: boolean,
        showNotification = true
    ): Promise<boolean> => {
        const shareState = getShareFetchState(shareId);
        let linkFetchMeta = shareState.folders[parentLinkId];
        if (!linkFetchMeta) {
            linkFetchMeta = {
                all: {},
                foldersOnly: {},
            };
            shareState.folders[parentLinkId] = linkFetchMeta;
        }
        if (foldersOnly) {
            // If request to query all items is in progress, lets wait
            // as that might fetch all folder children as well.
            await waitFor(() => !linkFetchMeta.all.isInProgress, { abortSignal });
            // If all items were downloaded, no need to perform fetch
            // for folders only.
            if (linkFetchMeta.all.isEverythingFetched) {
                return false;
            }
        }

        const fetchMeta = foldersOnly ? linkFetchMeta.foldersOnly : linkFetchMeta.all;
        return fetchNextPageWithSortingHelper(
            abortSignal,
            shareId,
            sorting,
            fetchMeta,
            (sorting: SortParams, page: number) => {
                return fetchChildrenPage(
                    abortSignal,
                    shareId,
                    parentLinkId,
                    sorting,
                    page,
                    foldersOnly,
                    showNotification
                );
            },
            showNotification
        );
    };

    const fetchLinksMeta = async (
        abortSignal: AbortSignal,
        shareId: string,
        linkIds: string[],
        loadThumbnails: boolean = false
    ): Promise<FetchResponse> => {
        const { Links, Parents } = await debouncedRequest<LinkMetaBatchPayload>(
            queryLinkMetaBatch(shareId, linkIds, loadThumbnails),
            abortSignal
        );

        return {
            links: Links.map((link) => linkMetaToEncryptedLink(link, shareId)),
            parents: Parents ? Object.values(Parents).map((link) => linkMetaToEncryptedLink(link, shareId)) : [],
        };
    };

    const loadLinksMeta: FetchLoadLinksMeta = async (abortSignal, query, shareId, linkIds, options = {}) => {
        const shareState = getShareFetchState(shareId);
        // Shared links use own state for fetch meta.
        let fetchMeta = options.fetchMeta || shareState.links[query];
        if (!fetchMeta) {
            fetchMeta = {};
            state.current[shareId].links[query] = fetchMeta;
        }
        await waitFor(() => !fetchMeta.isInProgress, { abortSignal });
        fetchMeta.isInProgress = true;

        const linksAcc: DecryptedLink[] = [];
        const parentsAcc: DecryptedLink[] = [];
        const errorsAcc: any[] = [];

        const load = async () => {
            const missingLinkIds: string[] = [];

            // Read cache to avoid unnescesary queries
            linkIds.forEach((linkId) => {
                const link = linksState.getLink(shareId, linkId);

                if (isLinkDecrypted(link)) {
                    linksAcc.push(link.decrypted);
                } else {
                    missingLinkIds.push(linkId);
                }
            });

            for (const pageLinkIds of chunk(missingLinkIds, BATCH_REQUEST_SIZE)) {
                const { links, parents } = await fetchLinksMeta(
                    abortSignal,
                    shareId,
                    pageLinkIds,
                    options.loadThumbnails
                );
                const cached = await cacheLoadedLinks(abortSignal, shareId, links, parents);

                if (cached.errors.length > 0) {
                    errorsAcc.push(...cached.errors);
                }

                for (const { decrypted } of cached.links) {
                    // Links should not include parents because parents need to be
                    // processed first otherwise links would do fetch automatically
                    // again before parents are properly handled. Normally loading
                    // should focus on links only, but for example, not all endpoints
